const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;

pub const DType = enum { f64, f32, i64, i32, c64 };

pub const Shape = []const usize;

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        @memset(data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn view(self: Tensor, new_shape: Shape) !Tensor {
        if (self.data.len != totalElements(new_shape)) return error.ShapeMismatch;
        const shape_copy = try self.allocator.dupe(usize, new_shape);
        var strides = try self.allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
        };
    }

    pub fn totalElements(shape: Shape) usize {
        var total: usize = 1;
        for (shape) |dim| total *= dim;
        return total;
    }

    pub fn matmul(self: Tensor, other: Tensor, result: *Tensor) !void {
        if (self.shape.len < 2 or other.shape.len < 2 or self.shape[self.shape.len - 1] != other.shape[other.shape.len - 2]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[self.shape.len - 2];
        const n = other.shape[other.shape.len - 1];
        const k = self.shape[self.shape.len - 1];
        if (result.shape.len != 2 or result.shape[0] != m or result.shape[1] != n) {
            return error.ResultShapeMismatch;
        }
        @memset(result.data, 0.0);
        const self_ptr = self.data.ptr + self.offset;
        const other_ptr = other.data.ptr + other.offset;
        const res_ptr = result.data.ptr;
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j + 3 < n) : (j += 4) {
                var sum0: f64 = 0.0;
                var sum1: f64 = 0.0;
                var sum2: f64 = 0.0;
                var sum3: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    const a_val = self_ptr[i * k + l];
                    sum0 += a_val * other_ptr[l * n + j + 0];
                    sum1 += a_val * other_ptr[l * n + j + 1];
                    sum2 += a_val * other_ptr[l * n + j + 2];
                    sum3 += a_val * other_ptr[l * n + j + 3];
                }
                res_ptr[i * n + j + 0] += sum0;
                res_ptr[i * n + j + 1] += sum1;
                res_ptr[i * n + j + 2] += sum2;
                res_ptr[i * n + j + 3] += sum3;
            }
            while (j < n) : (j += 1) {
                var sum: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    sum += self_ptr[i * k + l] * other_ptr[l * n + j];
                }
                res_ptr[i * n + j] += sum;
            }
        }
    }

    pub fn layernorm(self: Tensor, epsilon: f64, result: *Tensor) !void {
        if (self.shape.len != 1) return error.InvalidShapeForLayernorm;
        const n = self.shape[0];
        if (result.shape.len != 1 or result.shape[0] != n) return error.ResultShapeMismatch;
        const self_ptr = self.data.ptr + self.offset;
        const res_ptr = result.data.ptr;
        var mean: f64 = 0.0;
        var i: usize = 0;
        while (i < n) : (i += 1) {
            mean += self_ptr[i];
        }
        mean /= @as(f64, @floatFromInt(n));
        var var_sum: f64 = 0.0;
        i = 0;
        while (i < n) : (i += 1) {
            const diff = self_ptr[i] - mean;
            var_sum += diff * diff;
        }
        const variance = var_sum / @as(f64, @floatFromInt(n)) + epsilon;
        const stddev = math.sqrt(variance);
        i = 0;
        while (i < n) : (i += 1) {
            res_ptr[i] = (self_ptr[i] - mean) / stddev;
        }
    }

    pub fn softmax(self: Tensor, result: *Tensor) !void {
        if (self.shape.len != 1) return error.InvalidShapeForSoftmax;
        const n = self.shape[0];
        if (result.shape.len != 1 or result.shape[0] != n) return error.ResultShapeMismatch;
        const self_ptr = self.data.ptr + self.offset;
        const res_ptr = result.data.ptr;
        var max_val: f64 = self_ptr[0];
        var i: usize = 1;
        while (i < n) : (i += 1) {
            if (self_ptr[i] > max_val) max_val = self_ptr[i];
        }
        var sum_exp: f64 = 0.0;
        i = 0;
        while (i < n) : (i += 1) {
            sum_exp += math.exp(self_ptr[i] - max_val);
        }
        i = 0;
        while (i < n) : (i += 1) {
            res_ptr[i] = math.exp(self_ptr[i] - max_val) / sum_exp;
        }
    }

    pub fn spectral_norm(self: Tensor, result: *Tensor) !void {
        if (self.shape.len != 2) return error.InvalidShapeForSpectralNorm;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (result.shape.len != 1 or result.shape[0] != 1) return error.ResultShapeMismatch;
        const self_ptr = self.data.ptr + self.offset;
        const res_ptr = result.data.ptr;
        var u = try self.allocator.alloc(f64, rows);
        defer self.allocator.free(u);
        var v = try self.allocator.alloc(f64, cols);
        defer self.allocator.free(v);
        var norm_u: f64 = 1.0 / math.sqrt(@as(f64, @floatFromInt(rows)));
        @memset(u, norm_u);
        var norm_v: f64 = 0.0;
        var iter: usize = 0;
        while (iter < 10) : (iter += 1) {
            var j: usize = 0;
            while (j < cols) : (j += 1) {
                v[j] = 0.0;
                var l: usize = 0;
                while (l < rows) : (l += 1) {
                    v[j] += self_ptr[l * cols + j] * u[l];
                }
            }
            norm_v = 0.0;
            j = 0;
            while (j < cols) : (j += 1) {
                norm_v += v[j] * v[j];
            }
            norm_v = math.sqrt(norm_v);
            if (norm_v == 0.0) break;
            j = 0;
            while (j < cols) : (j += 1) {
                v[j] /= norm_v;
            }
            j = 0;
            while (j < rows) : (j += 1) {
                u[j] = 0.0;
                var l: usize = 0;
                while (l < cols) : (l += 1) {
                    u[j] += self_ptr[j * cols + l] * v[l];
                }
            }
            var norm_u_new: f64 = 0.0;
            j = 0;
            while (j < rows) : (j += 1) {
                norm_u_new += u[j] * u[j];
            }
            norm_u_new = math.sqrt(norm_u_new);
            if (norm_u_new == 0.0) break;
            j = 0;
            while (j < rows) : (j += 1) {
                u[j] /= norm_u_new;
            }
        }
        res_ptr[0] = norm_v;
    }

    pub fn add(self: Tensor, other: Tensor, result: *Tensor) !void {
        if (self.shape.len != other.shape.len) return error.ShapeMismatch;
        for (self.shape, 0..) |s_dim, i| {
            if (s_dim != other.shape[i]) return error.ShapeMismatch;
        }
        if (result.shape.len != self.shape.len) return error.ResultShapeMismatch;
        for (self.shape, 0..) |s_dim, i| {
            if (s_dim != result.shape[i]) return error.ResultShapeMismatch;
        }
        const self_ptr = self.data.ptr + self.offset;
        const other_ptr = other.data.ptr + other.offset;
        const res_ptr = result.data.ptr;
        const total = self.data.len;
        var i: usize = 0;
        while (i < total) : (i += 1) {
            res_ptr[i] = self_ptr[i] + other_ptr[i];
        }
    }

    pub fn mul(self: Tensor, other: Tensor, result: *Tensor) !void {
