    }
}

void tensor_random_uniform(Tensor *t, f64 min_val, f64 max_val) {
    if (!t || !t->data) return;
    f64 range = max_val - min_val;
    for (u32 i = 0; i < t->total; i++) {
        t->data[i] = min_val + ((f64)rand() / RAND_MAX) * range;
    }
}

void tensor_random_normal(Tensor *t, f64 mean, f64 stddev) {
    if (!t || !t->data) return;
    for (u32 i = 0; i < t->total; i++) {
        f64 u1 = ((f64)rand() + 1.0) / (RAND_MAX + 1.0);
        f64 u2 = ((f64)rand() + 1.0) / (RAND_MAX + 1.0);
        f64 z0 = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
        t->data[i] = mean + stddev * z0;
    }
}

int tensor_matmul(Tensor *a, Tensor *b, Tensor *result) {
    if (!a || !b || !result) return -1;
    if (a->ndim < 2 || b->ndim < 2) return -1;
    u32 m = a->shape[a->ndim - 2];
    u32 k = a->shape[a->ndim - 1];
    u32 n = b->shape[b->ndim - 1];
    if (k != b->shape[b->ndim - 2]) return -1;
    if (result->shape[result->ndim - 2] != m || result->shape[result->ndim - 1] != n) return -1;
    memset(result->data, 0, result->total * sizeof(f64));
    for (u32 i = 0; i < m; i++) {
        for (u32 j = 0; j < n; j += 4) {
            f64 sum0 = 0.0, sum1 = 0.0, sum2 = 0.0, sum3 = 0.0;
            for (u32 l = 0; l < k; l++) {
                f64 a_val = a->data[i * k + l];
                if (j + 0 < n) sum0 += a_val * b->data[l * n + j + 0];
                if (j + 1 < n) sum1 += a_val * b->data[l * n + j + 1];
                if (j + 2 < n) sum2 += a_val * b->data[l * n + j + 2];
                if (j + 3 < n) sum3 += a_val * b->data[l * n + j + 3];
            }
            if (j + 0 < n) result->data[i * n + j + 0] = sum0;
            if (j + 1 < n) result->data[i * n + j + 1] = sum1;
            if (j + 2 < n) result->data[i * n + j + 2] = sum2;
            if (j + 3 < n) result->data[i * n + j + 3] = sum3;
        }
    }
    return 0;
}

int tensor_add(Tensor *a, Tensor *b, Tensor *result) {
    if (!a || !b || !result) return -1;
    if (a->total != b->total || a->total != result->total) return -1;
    for (u32 i = 0; i < a->total; i++) {
        result->data[i] = a->data[i] + b->data[i];
    }
    return 0;
}

int tensor_sub(Tensor *a, Tensor *b, Tensor *result) {
    if (!a || !b || !result) return -1;
    if (a->total != b->total || a->total != result->total) return -1;
    for (u32 i = 0; i < a->total; i++) {
        result->data[i] = a->data[i] - b->data[i];
    }
    return 0;
}

int tensor_mul(Tensor *a, Tensor *b, Tensor *result) {
    if (!a || !b || !result) return -1;
    if (a->total != b->total || a->total != result->total) return -1;
    for (u32 i = 0; i < a->total; i++) {
        result->data[i] = a->data[i] * b->data[i];
    }
    return 0;
}

int tensor_div(Tensor *a, Tensor *b, Tensor *result) {
    if (!a || !b || !result) return -1;
    if (a->total != b->total || a->total != result->total) return -1;
    for (u32 i = 0; i < a->total; i++) {
        if (fabs(b->data[i]) < 1e-12) return -1;
        result->data[i] = a->data[i] / b->data[i];
    }
    return 0;
}

int tensor_scale(Tensor *t, f64 scalar, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = t->data[i] * scalar;
    }
    return 0;
}

f64 tensor_sum(Tensor *t) {
    if (!t) return 0.0;
    f64 sum = 0.0;
    for (u32 i = 0; i < t->total; i++) {
        sum += t->data[i];
    }
    return sum;
}

f64 tensor_mean(Tensor *t) {
    if (!t || t->total == 0) return 0.0;
    return tensor_sum(t) / (f64)t->total;
}

f64 tensor_variance(Tensor *t) {
    if (!t || t->total == 0) return 0.0;
    f64 mean = tensor_mean(t);
    f64 var_sum = 0.0;
    for (u32 i = 0; i < t->total; i++) {
        f64 diff = t->data[i] - mean;
        var_sum += diff * diff;
    }
    return var_sum / (f64)t->total;
}

int tensor_layernorm(Tensor *t, f64 epsilon, Tensor *result) {
    if (!t || !result) return -1;
    if (t->ndim != 1 || result->ndim != 1) return -1;
    u32 n = t->shape[0];
    if (result->shape[0] != n) return -1;
    f64 mean = 0.0;
    for (u32 i = 0; i < n; i++) {
        mean += t->data[i];
    }
    mean /= (f64)n;
    f64 var_sum = 0.0;
    for (u32 i = 0; i < n; i++) {
        f64 diff = t->data[i] - mean;
        var_sum += diff * diff;
    }
    f64 variance = var_sum / (f64)n + epsilon;
    f64 stddev = sqrt(variance);
    for (u32 i = 0; i < n; i++) {
        result->data[i] = (t->data[i] - mean) / stddev;
    }
    return 0;
}

int tensor_softmax(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->ndim != 1 || result->ndim != 1) return -1;
    u32 n = t->shape[0];
    if (result->shape[0] != n) return -1;
    f64 max_val = t->data[0];
    for (u32 i = 1; i < n; i++) {
        if (t->data[i] > max_val) max_val = t->data[i];
    }
    f64 sum_exp = 0.0;
    for (u32 i = 0; i < n; i++) {
        sum_exp += exp(t->data[i] - max_val);
    }
    for (u32 i = 0; i < n; i++) {
        result->data[i] = exp(t->data[i] - max_val) / sum_exp;
    }
    return 0;
}

int tensor_relu(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = (t->data[i] > 0.0) ? t->data[i] : 0.0;
    }
    return 0;
}

int tensor_gelu(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    const f64 coeff = 0.044715;
    const f64 sqrt_2_over_pi = sqrt(2.0 / M_PI);
    for (u32 i = 0; i < t->total; i++) {
        f64 x = t->data[i];
        f64 x_cubed = x * x * x;
        f64 tanh_arg = sqrt_2_over_pi * (x + coeff * x_cubed);
        result->data[i] = 0.5 * x * (1.0 + tanh(tanh_arg));
    }
    return 0;
}

int tensor_tanh(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = tanh(t->data[i]);
    }
    return 0;
}

int tensor_sigmoid(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = 1.0 / (1.0 + exp(-t->data[i]));
    }
    return 0;
}

int tensor_exp(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = exp(t->data[i]);
    }
    return 0;
}

int tensor_log(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        if (t->data[i] <= 0.0) return -1;
        result->data[i] = log(t->data[i]);
    }
    return 0;
}

int tensor_sqrt(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        if (t->data[i] < 0.0) return -1;
        result->data[i] = sqrt(t->data[i]);
    }
    return 0;
}

int tensor_pow(Tensor *t, f64 exponent, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        result->data[i] = pow(t->data[i], exponent);
    }
    return 0;
}

int tensor_clip(Tensor *t, f64 min_val, f64 max_val, Tensor *result) {
    if (!t || !result) return -1;
    if (t->total != result->total) return -1;
    for (u32 i = 0; i < t->total; i++) {
        if (t->data[i] < min_val) {
            result->data[i] = min_val;
        } else if (t->data[i] > max_val) {
            result->data[i] = max_val;
        } else {
            result->data[i] = t->data[i];
        }
    }
    return 0;
}

f64 tensor_dot(Tensor *a, Tensor *b) {
    if (!a || !b) return 0.0;
    if (a->total != b->total) return 0.0;
    f64 sum = 0.0;
    for (u32 i = 0; i < a->total; i++) {
        sum += a->data[i] * b->data[i];
    }
    return sum;
}

int tensor_transpose(Tensor *t, Tensor *result) {
    if (!t || !result) return -1;
    if (t->ndim != 2 || result->ndim != 2) return -1;
    u32 rows = t->shape[0];
    u32 cols = t->shape[1];
    if (result->shape[0] != cols || result->shape[1] != rows) return -1;
    for (u32 i = 0; i < rows; i++) {
        for (u32 j = 0; j < cols; j++) {
            result->data[j * rows + i] = t->data[i * cols + j];
        }
    }
    return 0;
}

int tensor_copy(Tensor *src, Tensor *dst) {
    if (!src || !dst) return -1;
    if (src->total != dst->total) return -1;
    memcpy(dst->data, src->data, src->total * sizeof(f64));
    return 0;
}

AdamState *adam_create(u32 size) {
    AdamState *state = (AdamState *)malloc(sizeof(AdamState));
    if (!state) return NULL;
    state->m = (f64 *)calloc(size, sizeof(f64));
    state->v = (f64 *)calloc(size, sizeof(f64));
    if (!state->m || !state->v) {
        free(state->m);
        free(state->v);
        free(state);
        return NULL;
    }
    state->t = 0;
    state->beta1 = 0.9;
    state->beta2 = 0.999;
    state->epsilon = 1e-8;
    return state;
}

void adam_free(AdamState *state) {
    if (!state) return;
    free(state->m);
    free(state->v);
    free(state);
}

int adam_update(Tensor *params, Tensor *grad, AdamState *state, f64 lr) {
    if (!params || !grad || !state) return -1;
    if (params->total != grad->total) return -1;
    state->t++;
    for (u32 i = 0; i < params->total; i++) {
        state->m[i] = state->beta1 * state->m[i] + (1.0 - state->beta1) * grad->data[i];
        state->v[i] = state->beta2 * state->v[i] + (1.0 - state->beta2) * grad->data[i] * grad->data[i];
        f64 m_hat = state->m[i] / (1.0 - pow(state->beta1, (f64)state->t));
        f64 v_hat = state->v[i] / (1.0 - pow(state->beta2, (f64)state->t));
        params->data[i] -= lr * m_hat / (sqrt(v_hat) + state->epsilon);
    }
    return 0;
}

RMSPropState *rmsprop_create(u32 size) {
    RMSPropState *state = (RMSPropState *)malloc(sizeof(RMSPropState));
    if (!state) return NULL;
    state->g = (f64 *)calloc(size, sizeof(f64));
    if (!state->g) {
        free(state);
        return NULL;
    }
    state->t = 0;
    state->alpha = 0.99;
    state->epsilon = 1e-8;
    return state;
}

void rmsprop_free(RMSPropState *state) {
    if (!state) return;
    free(state->g);
    free(state);
}

int rmsprop_update(Tensor *params, Tensor *grad, RMSPropState *state, f64 lr) {
    if (!params || !grad || !state) return -1;
    if (params->total != grad->total) return -1;
    state->t++;
    for (u32 i = 0; i < params->total; i++) {
        state->g[i] = state->alpha * state->g[i] + (1.0 - state->alpha) * grad->data[i] * grad->data[i];
        params->data[i] -= lr * grad->data[i] / (sqrt(state->g[i]) + state->epsilon);
    }
    return 0;
}

int sgd_update(Tensor *params, Tensor *grad, f64 lr) {
    if (!params || !grad) return -1;
    if (params->total != grad->total) return -1;
    for (u32 i = 0; i < params->total; i++) {
        params->data[i] -= lr * grad->data[i];
    }
    return 0;
}

f64 cross_entropy_loss(Tensor *logits, Tensor *targets, u32 batch_size, u32 classes) {
    if (!logits || !targets) return -1.0;
    if (logits->shape[0] != batch_size || logits->shape[1] != classes) return -1.0;
    if (targets->shape[0] != batch_size) return -1.0;
    f64 loss = 0.0;
    for (u32 b = 0; b < batch_size; b++) {
        f64 max_logit = logits->data[b * classes];
        for (u32 i = 1; i < classes; i++) {
            if (logits->data[b * classes + i] > max_logit) {
                max_logit = logits->data[b * classes + i];
            }
        }
        f64 log_sum_exp = 0.0;
        for (u32 i = 0; i < classes; i++) {
            log_sum_exp += exp(logits->data[b * classes + i] - max_logit);
        }
        log_sum_exp = log(log_sum_exp) + max_logit;
        u32 target_idx = (u32)targets->data[b];
        if (target_idx >= classes) return -1.0;
        loss -= logits->data[b * classes + target_idx] - log_sum_exp;
    }
    return loss / (f64)batch_size;
}

f64 mse_loss(Tensor *pred, Tensor *target) {
    if (!pred || !target) return -1.0;
    if (pred->total != target->total) return -1.0;
    f64 loss = 0.0;
    for (u32 i = 0; i < pred->total; i++) {
        f64 diff = pred->data[i] - target->data[i];
        loss += diff * diff;
    }
    return loss / (f64)pred->total;
}

int tensor_save(Tensor *t, const char *filename) {
    if (!t || !filename) return -1;
    FILE *f = fopen(filename, "wb");
    if (!f) return -1;
    fwrite(&t->ndim, sizeof(u32), 1, f);
    fwrite(t->shape, sizeof(u32), t->ndim, f);
    fwrite(&t->total, sizeof(u32), 1, f);
    fwrite(t->data, sizeof(f64), t->total, f);
    fclose(f);
    return 0;
}

Tensor *tensor_load(const char *filename) {
    if (!filename) return NULL;
    FILE *f = fopen(filename, "rb");
    if (!f) return NULL;
    u32 ndim;
    if (fread(&ndim, sizeof(u32), 1, f) != 1) {
        fclose(f);
        return NULL;
    }
    u32 *shape = (u32 *)malloc(ndim * sizeof(u32));
    if (!shape) {
        fclose(f);
        return NULL;
    }
    if (fread(shape, sizeof(u32), ndim, f) != ndim) {
        free(shape);
        fclose(f);
        return NULL;
    }
    u32 total;
    if (fread(&total, sizeof(u32), 1, f) != 1) {
        free(shape);
        fclose(f);
        return NULL;
    }
    Tensor *t = tensor_create(shape, ndim);
    free(shape);
    if (!t) {
        fclose(f);
        return NULL;
    }
    if (fread(t->data, sizeof(f64), total, f) != total) {
        tensor_free(t);
        fclose(f);
        return NULL;
    }
    fclose(f);
    return t;
}

void tensor_print(Tensor *t) {
    if (!t) return;
    printf("Tensor shape: [");
    for (u32 i = 0; i < t->ndim; i++) {
        printf("%u", t->shape[i]);
        if (i < t->ndim - 1) printf(", ");
    }
    printf("]\n");
    printf("Data (first 10): ");
    u32 print_count = (t->total < 10) ? t->total : 10;
    for (u32 i = 0; i < print_count; i++) {
        printf("%.4f ", t->data[i]);
    }
    printf("\n");
}

int main(void) {
    srand((unsigned int)time(NULL));
    u32 shape_a[] = {2, 3};
    u32 shape_b[] = {3, 2};
    u32 shape_c[] = {2, 2};
    Tensor *a = tensor_create(shape_a, 2);
    Tensor *b = tensor_create(shape_b, 2);
    Tensor *c = tensor_create(shape_c, 2);
    tensor_random_uniform(a, -1.0, 1.0);
    tensor_random_uniform(b, -1.0, 1.0);
    printf("Matrix A:\n");
    tensor_print(a);
    printf("Matrix B:\n");
    tensor_print(b);
    if (tensor_matmul(a, b, c) == 0) {
        printf("Matrix C (A x B):\n");
        tensor_print(c);
    }
    u32 shape_vec[] = {5};
    Tensor *vec = tensor_create(shape_vec, 1);
    Tensor *norm_vec = tensor_create(shape_vec, 1);
    tensor_random_normal(vec, 0.0, 1.0);
    printf("Vector:\n");
    tensor_print(vec);
    if (tensor_layernorm(vec, 1e-5, norm_vec) == 0) {
        printf("Normalized vector:\n");
        tensor_print(norm_vec);
    }
    Tensor *soft_vec = tensor_create(shape_vec, 1);
    if (tensor_softmax(vec, soft_vec) == 0) {
        printf("Softmax vector:\n");
        tensor_print(soft_vec);
        printf("Softmax sum: %.6f\n", tensor_sum(soft_vec));
    }
    AdamState *adam = adam_create(vec->total);
    Tensor *grad = tensor_create(shape_vec, 1);
    tensor_random_normal(grad, 0.0, 0.1);
    printf("Before Adam update:\n");
    tensor_print(vec);
    adam_update(vec, grad, adam, 0.001);
    printf("After Adam update:\n");
    tensor_print(vec);
    tensor_free(a);
    tensor_free(b);
    tensor_free(c);
    tensor_free(vec);
    tensor_free(norm_vec);
    tensor_free(soft_vec);
    tensor_free(grad);
    adam_free(adam);
    return 0;
}
